function leaguePositionChart(points: any[]): string {
    if (!points?.length) return '<div class="muted">No league history available yet.</div>';
    const hasLevel = (value: any) => Number.isInteger(Number(value)) && Number(value) > 0;
    const known = points.filter(p => hasLevel(p.league_level));
    if (!known.length) return '<div class="muted">No reliable league tier is recorded for the available leagues.</div>';
    const W = 760, H = Math.max(250, 112 + new Set(known.map(p => Number(p.league_level))).size * 64), left = 165, right = 32, top = 42, bottom = 62;
    const levels = [...new Set(known.map(p => Number(p.league_level)))].sort((a,b)=>a-b);
    const x = (i: number) => left + i * (W-left-right) / Math.max(1, points.length-1);
    const lane = (level: number) => top + levels.indexOf(level) * (H-top-bottom) / Math.max(1, levels.length-1);
    const coords = points.map((p,i)=>hasLevel(p.league_level) ? {p,i,x:x(i),y:lane(Number(p.league_level))} : null).filter(Boolean) as any[];
    const leagueAtLevel = (level:number) => [...known].reverse().find(p=>Number(p.league_level)===level)?.league_name || "League";
    let path = "";
    coords.forEach((c,index)=>{ if(index===0) path=`M ${c.x} ${c.y}`; else path += ` H ${c.x} V ${c.y}`; });
    return `<div class="chart analysis-chart league-journey-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="League path and season positions">
      ${levels.map(level=>`<line class="chart-grid-line" x1="${left}" y1="${lane(level)}" x2="${W-right}" y2="${lane(level)}"/><text class="chart-axis-label league-lane-label" x="${left-12}" y="${lane(level)+4}" text-anchor="end">${esc(leagueAtLevel(level))}</text>`).join("")}
      <path class="chart-line league-step-line" d="${path}" fill="none"/>
      ${coords.map(c=>{ const result=String(c.p.position_display || "–"); const badgeWidth=Math.max(34, Math.min(92, 16 + result.length * 6.2)); return `<circle class="chart-point" cx="${c.x}" cy="${c.y}" r="7"><title>${esc(c.p.season_label)} · ${esc(c.p.league_name)} · ${esc(result)}</title></circle><g class="league-position-badge"><rect x="${c.x-badgeWidth/2}" y="${c.y-37}" width="${badgeWidth}" height="22" rx="11"></rect><text x="${c.x}" y="${c.y-22}" text-anchor="middle">${esc(result)}</text></g><text class="chart-axis-label" x="${c.x}" y="${H-18}" text-anchor="middle">${esc(c.p.season_label)}</text>`;}).join("")}
    </svg><p class="chart-note">The line shows the league path. The number at each point is the final position or current table position.</p></div>`;
}

function horizontalBars(items: any[], valueKey = "count", labelKey = "label", suffix = ""): string {
    if (!items?.length) return '<div class="muted">No data in the selected period.</div>';
    const max = Math.max(1, ...items.map(item => Number(item[valueKey]) || 0));
    return `<div class="horizontal-bars">${items.map(item => {
      const value = Number(item[valueKey]) || 0;
      const width = Math.max(value > 0 ? 4 : 0, value / max * 100);
      return `<div class="horizontal-bar-row"><div class="horizontal-bar-label"><span>${esc(item[labelKey] || "–")}</span><b>${num(value)}${esc(suffix)}</b></div><div class="horizontal-bar-track"><i style="width:${width}%"></i></div>${item.average_overall != null ? `<small>Avg. OVR ${num(item.average_overall,1)}</small>` : ""}</div>`;
    }).join("")}</div>`;
}

function simpleBarChart(points: any[], keys: Array<{key: string; label: string}>): string {
    if (!points?.length) return '<div class="muted">No data in the selected period.</div>';
    const W = 720, H = 230, left = 40, right = 18, top = 24, bottom = 46;
    const max = Math.max(1, ...points.flatMap(p => keys.map(k => Number(p[k.key]) || 0)));
    const groupWidth = (W - left - right) / Math.max(1, points.length);
    const barWidth = Math.max(7, Math.min(24, (groupWidth - 10) / Math.max(1, keys.length)));
    const y = (value: number) => top + (max - value) * (H - top - bottom) / max;
    return `<div class="chart analysis-chart"><svg viewBox="0 0 ${W} ${H}">
      <line class="chart-grid-line" x1="${left}" y1="${H-bottom}" x2="${W-right}" y2="${H-bottom}"/>
      ${points.map((p, i) => {
        const center = left + groupWidth * i + groupWidth / 2;
        const bars = keys.map((key, ki) => {
          const value = Number(p[key.key]) || 0;
          const x = center - (keys.length * barWidth) / 2 + ki * barWidth;
          return `<rect class="chart-bar series-${ki}" x="${x}" y="${y(value)}" width="${Math.max(4, barWidth-2)}" height="${H-bottom-y(value)}"><title>${esc(p.season_label)} · ${esc(key.label)}: ${num(value)}</title></rect>`;
        }).join("");
        return `${bars}<text class="chart-axis-label" x="${center}" y="${H-14}" text-anchor="middle">${esc(p.season_label)}</text>`;
      }).join("")}
    </svg><div class="chart-legend">${keys.map((k, i) => `<span><i class="series-${i}"></i>${esc(k.label)}</span>`).join("")}</div></div>`;
}

function radarChart(points: Array<{label:string; value:number}>): string {
    const rows = (points || []).filter(point => Number.isFinite(Number(point.value))).slice(0, 8);
    if (rows.length < 3) return '<div class="muted">Not enough attributes are available for a profile yet.</div>';
    const W = 760, H = 560, cx = 380, cy = 272, radius = 188;
    const angle = (index:number) => -Math.PI / 2 + index * Math.PI * 2 / rows.length;
    const xy = (index:number, factor:number) => ({x:cx + Math.cos(angle(index))*radius*factor, y:cy + Math.sin(angle(index))*radius*factor});
    const polygon = (factor:number) => rows.map((_,index)=>{const p=xy(index,factor);return `${p.x},${p.y}`;}).join(" ");
    const valuePolygon = rows.map((row,index)=>{const p=xy(index,Math.max(0,Math.min(100,Number(row.value)))/100);return `${p.x},${p.y}`;}).join(" ");
    return `<div class="chart player-radar-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Attribute profile">
      ${[.25,.5,.75,1].map(level=>`<polygon class="radar-grid" points="${polygon(level)}"></polygon>`).join("")}
      ${rows.map((_,index)=>{const p=xy(index,1);return `<line class="radar-axis" x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}"></line>`;}).join("")}
      <polygon class="radar-value" points="${valuePolygon}"></polygon>
      ${rows.map((row,index)=>{const p=xy(index,1.14);return `<text class="radar-label" x="${p.x}" y="${p.y}" text-anchor="middle"><tspan x="${p.x}">${esc(row.label)}</tspan><tspan class="radar-number" x="${p.x}" dy="14">${num(row.value,1)}</tspan></text>`;}).join("")}
    </svg></div>`;
}

function recordCatalog(records: any): string {
    const playerRows = records?.playerRecords || [];
    const positionRows = records?.positionRecords || [];
    const matchRows = records?.matchRecords || [];
    const streakRows = records?.streakRecords || [];
    const transferRows = records?.transferRecords || [];
    const recordValue = (row: any) => row.value_type === "money" ? money(row.value) : row.value_type === "rating" ? ratingValue(row.value, true) : row.value_type === "rate" ? `${num(row.value,2)} / Match` : row.value_type === "text" ? esc(row.value) : num(row.value);
    const playerTable = playerRows.length ? table([
      {label:"Record"},{label:"Player"},{label:"Value",cls:"num"},{label:"appearances",cls:"num"}
    ], playerRows.map((row:any)=>`<tr><td><strong>${esc(row.label)}</strong></td><td>${row.player_ea_id ? playerLink(row.player_ea_id,row.display_name) : esc(row.display_name || "–")}</td><td class="num"><strong>${recordValue(row)}</strong></td><td class="num">${row.appearances != null ? num(row.appearances) : "–"}</td></tr>`)) : '<div class="card-body"><span class="muted">No player records available.</span></div>';
    const positionTable = positionRows.length ? `<div class="position-record-grid">${positionRows.map((group:any)=>`<section class="position-record-card"><h3>${esc(group.group)}</h3>${table([{label:"Record"},{label:"Player"},{label:"Value",cls:"num"}],(group.records||[]).map((row:any)=>`<tr><td>${esc(row.label)}</td><td>${row.player_ea_id ? playerLink(row.player_ea_id,row.display_name) : esc(row.display_name || "–")}</td><td class="num"><strong>${recordValue(row)}</strong></td></tr>`))}</section>`).join("")}</div>` : '<span class="muted">No position records available.</span>';
    const eventCards = [...matchRows, ...transferRows].map((row:any)=>`<div class="record-card"><span>${esc(row.label)}</span><strong>${recordValue(row)}</strong><small>${row.display_name ? (row.player_ea_id ? playerLink(row.player_ea_id,row.display_name) : esc(row.display_name)) : row.fixture_id ? matchLink(row.fixture_id, row.opponent ? `vs ${row.opponent}` : "Open match") : esc(row.opponent || "")}${row.date ? ` · ${dateText(row.date)}` : ""}${row.competition_name ? ` · ${esc(row.competition_name)}` : ""}</small></div>`).join("");
    const streakCards = streakRows.map((row:any)=>`<div class="record-card"><span>${esc(row.label)}</span><strong>${num(row.value)} matches</strong><small>${row.start_date ? `${dateText(row.start_date)} to ${dateText(row.end_date)}` : ""}</small></div>`).join("");
    return `<section class="card records-section"><header class="card-header"><h2>Records</h2><span>${esc(records?.periodLabel || "selected period")}</span></header><div class="records-grid"><div>${playerTable}</div><div class="record-card-grid">${eventCards || '<span class="muted">No match or transfer records available.</span>'}${streakCards}</div></div><section class="position-records"><div class="card-title-row"><h3 class="card-title">Position records</h3><span>within position groups</span></div>${positionTable}</section><div class="record-notes">${(records?.notes || []).map((note:any)=>`<span>${esc(note)}</span>`).join("")}</div></section>`;
}

function qualityPanel(quality: any): string {
    const icon = (level: string) => level === "good" ? "✓" : level === "warn" ? "!" : "i";
    return `<section class="card pad"><h3 class="card-title">Data quality</h3><div class="quality-list">${(quality?.items || []).map((item: any) => `<div class="quality-item ${esc(item.level)}"><b>${icon(item.level)}</b><span>${esc(item.label)}</span></div>`).join("")}</div></section>`;
}

function periodPicker(options: any[], selected: number, attribute: "analysis" | "records"): string {
    const dataAttribute = attribute === "records" ? "data-records-season" : "data-analysis-season";
    return `<label class="page-filter"><span>Period</span><select ${dataAttribute}><option value="-1" ${selected === -1 ? "selected" : ""}>All seasons</option>${options.map((option: any) => `<option value="${option.season_index}" ${Number(option.season_index) === Number(selected) ? "selected" : ""}>${esc(option.label)}${option.is_current ? " · current" : ""}</option>`).join("")}</select></label>`;
}

function analysisTabs(active: string): string {
    return `<div class="page-tabs analysis-tabs"><button class="${active === "overview" ? "active" : ""}" data-analysis-tab="overview">Overview</button><button class="${active === "performance" ? "active" : ""}" data-analysis-tab="performance">Match data</button><button class="${active === "commission" ? "active" : ""}" data-analysis-tab="commission">Technical commission</button><button class="${active === "squad" ? "active" : ""}" data-analysis-tab="squad">Squad analysis</button><button class="${active === "seasons" ? "active" : ""}" data-analysis-tab="seasons">Season comparison</button></div>`;
}

function technicalCommission(d: any, reportCache: any = null): string {
    const coverage = d?.coverage || {}, players = d?.players || [];
    const briefing=d?.briefingOptions||{}, completedMatches=briefing.matches||[], upcomingMatches=briefing.upcoming||[];
    const fixtureLabel=(m:any,completed:boolean)=>`${dateText(m.date)} · ${esc(m.home||"?")} ${completed&&m.home_score!=null?`${num(m.home_score)}–${num(m.away_score)}`:"v"} ${esc(m.away||"?")} · ${esc(m.competition||"")}${completed&&!m.detailed_stats_available?" · basic facts only":""}`;
    const reportMatchOptions=completedMatches.map((m:any)=>`<option value="${m.fixture_id}">${fixtureLabel(m,true)}</option>`).join("");
    const reportNextOptions=upcomingMatches.map((m:any)=>`<option value="${m.fixture_id}">${fixtureLabel(m,false)}</option>`).join("");
    const reportPlayerOptions=players.map((p:any)=>`<option value="${p.player_ea_id}">${esc(p.display_name)} · ${esc(p.position||"N/D")}</option>`).join("");
    const rows = players.map((p: any) => { const m=p.metrics||{}; return `<tr><td>${p.player_ea_id ? playerLink(p.player_ea_id, p.display_name) : esc(p.display_name)}</td><td class="center">${positionBadge(p.position)}</td><td>${esc(p.hierarchy_label || "N/D")}</td><td class="num">${p.minutes ? num(p.minutes) : "N/D"}</td><td class="num">${p.season_rating == null ? "N/D" : num(p.season_rating, 2)}</td><td class="num">${p.recent_rating == null ? "N/D" : num(p.recent_rating, 2)}</td><td>${esc(p.sample?.label || "N/D")}${p.valid_form_games ? `<small class="table-subline">${num(p.valid_form_games)} atuações · ${num(p.recent_appearances)} recentes</small>` : ""}</td><td class="num">${m.appearances ? `${num(m.npk_goals)} / ${num(m.assists)}` : "N/D"}<small class="table-subline">${m.appearances?`${num(m.appearances)} jogos · ${esc(m.sample?.label||"N/D")}`:"NPK G / A · MatchStats"}</small></td><td class="num">${m.npk_expected_goals == null ? "N/D" : num(m.npk_expected_goals,2)} / ${m.expected_assists == null ? "N/D" : num(m.expected_assists,2)}<small class="table-subline">xG / xA</small></td><td class="num">${m.appearances ? num(m.shots) : "N/D"}<small class="table-subline">${m.shot_accuracy_pct==null?"N/D":`${num(m.shot_accuracy_pct,1)} % no alvo`}</small></td><td class="num">${m.pass_accuracy_pct==null?"N/D":`${num(m.pass_accuracy_pct,1)} %`}</td><td class="num">${m.appearances ? `${num(m.tackles)} / ${num(m.interceptions)}` : "N/D"}<small class="table-subline">desarmes / interceptações</small></td><td class="num">${m.appearances ? `${num(m.blocks)} / ${num(m.clearances)}` : "N/D"}<small class="table-subline">bloqueios / cortes</small></td><td class="num">${m.appearances ? `${num(m.saves)} / ${num(m.goals_conceded)}` : "N/D"}<small class="table-subline">defesas / gols sofridos</small></td><td>${esc(p.moment || "N/D")}</td><td>${esc(p.recommendation || "N/D")}</td></tr>`; }).join("");
    const posRows=(d.position_comparisons||[]).map((r:any)=>`<tr><td>${esc(r.position)}</td><td class="num">${num(r.players)}</td><td class="num">${num(r.matches)}</td><td class="num">${num(r.minutes)}</td><td class="num">${r.average_rating==null?"N/D":num(r.average_rating,2)}</td><td class="num">${r.goals_per90==null?"N/D":num(r.goals_per90,2)}</td><td class="num">${r.xg_per90==null?"N/D":num(r.xg_per90,2)}</td><td>${esc(r.sample?.label||"N/D")}</td></tr>`).join("");
    const fnRows=(d.function_comparisons||[]).map((r:any)=>`<tr><td>${esc(r.position)}</td><td class="num">${num(r.players)}</td><td class="num">${num(r.matches)}</td><td class="num">${num(r.minutes)}</td><td class="num">${r.average_rating==null?"N/D":num(r.average_rating,2)}</td><td class="num">${r.goals_per90==null?"N/D":num(r.goals_per90,2)}</td><td>${esc(r.sample?.label||"N/D")}</td></tr>`).join("");
    const identity=d.team_identity||{}, tm=identity.metrics||{}, cached=reportCache?.result||{}, ai=cached.report||{};
    const refs=(ids:any[])=>{const catalog=new Map((cached.fact_catalog||[]).map((f:any)=>[f.id,f.label]));return esc((ids||[]).map((id:any)=>catalog.get(id)||id).join(" · "));};
    const kindLabel=(kind:string)=>kind==="fact"?tr("claimFact"):kind==="hypothesis"?tr("claimHypothesis"):tr("claimInference");
    const reportItems=(items:any[])=>items?.length?`<ul>${items.map((item:any)=>`<li><span class="commission-claim-kind ${esc(item.kind||"inference")}">${esc(kindLabel(item.kind))}</span> ${esc(item.text)}${item.kind==="hypothesis"&&item.limitations?`<small class="commission-claim-limit">${tr("claimLimit")}: ${esc(item.limitations)}</small>`:""}<small class="table-subline">Atlas: ${refs(item.fact_refs)}</small></li>`).join("")}</ul>`:"";
    const profileRows=(identity.opponent_profiles||[]).map((item:any)=>`<div class="commission-profile-card"><strong>${esc(item.opponent_profile)}</strong><span>${item.reading==="maior_facilidade_observada"?"Melhor desempenho":item.reading==="maior_dificuldade_observada"?"Maior dificuldade":"Sem comparação"}</span><small>${num(item.matches)} jogos · ${num(item.points_per_match,2)} pts/jogo · saldo ${num(item.goal_difference_per_match,2)}/jogo</small></div>`).join("");
    const reportState=reportCache?.state||"missing";
    const reportNote=ai.commission_note?.text?`<p class="commission-note"><strong>${tr("commissionNote")}:</strong> ${esc(ai.commission_note.text)}</p>`:"";
    const reportSummary=reportState==="ready"?`<div class="commission-report-head"><strong>${esc(ai.summary?.text||"Análise salva.")}</strong><small><span class="commission-claim-kind ${esc(ai.summary?.kind||"inference")}">${esc(kindLabel(ai.summary?.kind))}</span> · ${esc(cached.model||"Ollama local")} · ${esc(reportCache.generated_at||"Atlas")}<br>Fatos: ${refs(ai.summary?.fact_refs)}</small></div>${ai.summary?.limitations?`<p class="commission-claim-limit">${tr("claimLimit")}: ${esc(ai.summary.limitations)}</p>`:""}${reportNote}${reportItems(ai.observations)}${reportItems(ai.recommendations)}${commissionFollowupForm(ai.information_requests,{snapshot_id:Number(d.snapshot_id),mode:"team_identity",model:cached.model,coach_context:cached.fact_catalog?.find((f:any)=>f.id==="coach_context")?.value})}<details class="report-provenance"><summary>Cobertura e validação das evidências</summary><small>${num(cached.coverage?.previous_linked_matches)} partidas anteriores · ${num(cached.validation?.accepted_claims)} afirmações mantidas · ${num(cached.validation?.rejected_claims)} filtradas · ${esc(cached.validation?.interpretation_quality||"Qualidade interpretativa não avaliada independentemente")}</small></details>`:reportState==="queued"||reportState==="running"?`<p>Ollama está preparando a leitura do estilo em segundo plano. O restante do Atlas continua disponível.</p>`:reportState==="stale"?`<p>A leitura salva ficou desatualizada após a entrada de novos dados. Atualize para usar as estatísticas atuais.</p><div class="commission-report-head"><strong>${esc(ai.summary?.text||"")}</strong></div>`:`<p>A leitura da comissão será salva e reutilizada enquanto as estatísticas usadas não mudarem.</p>`;
    const retroactiveBatch=`<section class="card pad commission-retroactive"><div class="card-title-row"><div><h3 class="card-title">${tr("retroTitle")}</h3><p class="chart-note">${tr("retroHelp")}</p></div><button class="button primary" data-retroactive-reports data-season-index="${num(d.selectedSeasonIndex)}">${tr("retroStart")}</button></div><div data-retroactive-progress class="commission-report-output" aria-live="polite"></div></section>`;

    // P2 uses the same canonical Atlas contract as the existing commission tables.
    // Scores are shown as recorded, without inferring wins from ambiguous team names.
    const p2Language = atlasLanguage();
    const p2Words = p2Language==="en-GB" ? {
        overview:"Technical Commission · Season overview",npkxg:"NPK-xG / match",shots:"Shots / match",passes:"Pass accuracy",tackles:"Tackles / match",comparisons:"Position comparisons",comparable:"players with usable samples",team:"Observed team indicators",sample:"Sample coverage",recent:"Recently completed fixtures",recentNote:"Recorded results; not a tactical classification",form:"Player form relative to season",formNote:"Last five valid appearances versus season rating; minimum usable sample",up:"Above season average",down:"Below season average",steady:"No qualifying player in this group",insights:"Technical interpretation",insightsNote:"Saved local report; all AI claims retain source references",action:"Refresh staff reading",generate:"Generate staff reading",hint:"No supported team report yet. The statistical view remains available.",pos:"By registered position",observed:"By observed match position",compNote:"Ordered by minutes, not ranked by quality; small samples must not justify conclusions",details:"Opponent shot-volume cohorts",detailsNote:"Descriptive cohorts only; not opponent tactics or a causal explanation",method:"Coverage, data quality and statistical detail",full:"MatchStats and player comparison tables",recentStatus:"Detailed FC26 match data",basicStatus:"Basic result only",matches:"matches",min:"min",rating:"Rating",coverage:"Detailed matches",noRecent:"No completed matches available in this scope.",noCompare:"No position observations in this scope.",noReport:"Report not yet available",notReady:"A saved report needs refresh after new source data.",review:"Some claims need review; check the underlying sources."
    } : p2Language==="es-ES" ? {
        overview:"Comisión técnica · Temporada",npkxg:"NPK-xG / partido",shots:"Remates / partido",passes:"Precisión de pase",tackles:"Entradas / partido",comparisons:"Comparaciones por posición",comparable:"jugadores con muestra utilizable",team:"Indicadores observados",sample:"Cobertura de la muestra",recent:"Partidos registrados recientemente",recentNote:"Resultados registrados; no son etiquetas tácticas",form:"Forma individual frente a la temporada",formNote:"Últimas cinco actuaciones válidas frente a la nota de temporada, con muestra mínima",up:"Por encima de la media",down:"Por debajo de la media",steady:"Sin jugadores con muestra y diferencia suficientes",insights:"Interpretación técnica",insightsNote:"Informe local guardado; afirmaciones con fuentes",action:"Actualizar análisis",generate:"Generar análisis",hint:"Aún no hay un informe de equipo sustentado. Las estadísticas siguen disponibles.",pos:"Por posición registrada",observed:"Por posición observada",compNote:"Ordenado por minutos, no por calidad; muestras pequeñas no prueban rendimiento",details:"Grupos por remates rivales",detailsNote:"Solo descripción; no implica táctica ni causalidad",method:"Cobertura, calidad de datos y detalle estadístico",full:"Tablas completas de MatchStats y jugadores",recentStatus:"Partido FC26 detallado",basicStatus:"Solo resultado básico",matches:"partidos",min:"min",rating:"Nota",coverage:"Partidos detallados",noRecent:"Sin partidos finalizados en este recorte.",noCompare:"Sin posiciones registradas en este recorte.",noReport:"Informe todavía no disponible",notReady:"El informe guardado necesita actualizarse tras nuevos datos.",review:"Algunas afirmaciones requieren revisión; consulte las fuentes."
    } : {
        overview:"Comissão Técnica · Panorama da temporada",npkxg:"NPK-xG / jogo",shots:"Finalizações / jogo",passes:"Precisão de passes",tackles:"Desarmes / jogo",comparisons:"Comparações por posição",comparable:"atletas com amostra utilizável",team:"Indicadores coletivos observados",sample:"Cobertura da amostra",recent:"Últimas partidas registradas",recentNote:"Resultados registrados, sem classificação tática inferida",form:"Forma individual em contexto",formNote:"Até cinco atuações válidas versus média da temporada, com amostra utilizável",up:"Acima da própria média",down:"Abaixo da própria média",steady:"Nenhum jogador com amostra e diferença suficientes neste grupo",insights:"Leitura da Comissão Técnica",insightsNote:"Relatório local salvo; conclusões com referências às evidências",action:"Atualizar leitura",generate:"Gerar leitura",hint:"Ainda não há interpretação coletiva validada. As estatísticas permanecem disponíveis.",pos:"Por posição cadastrada",observed:"Por posição observada na partida",compNote:"Ordenado por minutos, não por qualidade; amostras pequenas não comprovam desempenho",details:"Recortes por volume de chutes adversários",detailsNote:"Comparação descritiva; não determina a tática do adversário nem prova causalidade",method:"Cobertura, qualidade e detalhes estatísticos",full:"Tabelas completas do elenco e das posições",recentStatus:"MatchStats detalhado",basicStatus:"Apenas resultado básico",matches:"partidas",min:"min",rating:"Nota",coverage:"Partidas detalhadas",noRecent:"Nenhuma partida concluída disponível neste recorte.",noCompare:"Sem observações de posição válidas neste recorte.",noReport:"Relatório ainda indisponível",notReady:"O relatório salvo precisa ser atualizado após mudanças nos dados.",review:"Algumas afirmações exigem revisão; consulte as fontes."
    };
    const p2MetricItems = [
        {label:p2Words.npkxg,value:tm.npk_xg_per_match,precision:2},
        {label:p2Words.shots,value:tm.shots_per_match,precision:1},
        {label:p2Words.passes,value:tm.pass_accuracy_pct,precision:1,suffix:"%"},
        {label:p2Words.tackles,value:tm.tackles_per_match,precision:1}
    ];
    const p2MetricsPanel = `<section class="commission-p2-metrics" aria-label="${esc(p2Words.team)}">${p2MetricItems.map(item=>`<article class="commission-p2-metric"><span>${esc(item.label)}</span><strong>${item.value==null?"N/D":num(item.value,item.precision)}${item.value==null?"":(item.suffix||"")}</strong><small>${esc(p2Words.coverage)}: ${num(identity.detailed_matches)}</small></article>`).join("")}</section>`;
    const p2UsablePlayers = players.filter((p:any)=>p.sample?.usable===true && p.recent_delta!=null && p.season_rating!=null && p.recent_rating!=null);
    const p2Rising = p2UsablePlayers.filter((p:any)=>Number(p.recent_delta)>=0.3).sort((a:any,b:any)=>Number(b.recent_delta)-Number(a.recent_delta)).slice(0,5);
    const p2Falling = p2UsablePlayers.filter((p:any)=>Number(p.recent_delta)<=-0.3).sort((a:any,b:any)=>Number(a.recent_delta)-Number(b.recent_delta)).slice(0,5);
    const p2FormRows=(items:any[])=>items.length?items.map((p:any)=>`<article class="commission-p2-form-row"><div class="commission-p2-form-player"><strong>${playerLink(p.player_ea_id,p.display_name)}</strong><small>${esc(p.position||"N/D")} · ${num(p.valid_form_games)} ${esc(p2Words.matches)} · ${esc(p.sample?.label||"N/D")}</small></div><div class="commission-p2-form-numbers"><strong>${num(p.recent_rating,2)}</strong><small>${num(p.season_rating,2)} ${esc(p2Words.rating)} · ${p.recent_delta>0?"+":""}${num(p.recent_delta,2)}</small></div></article>`).join("") : `<p class="muted commission-p2-empty">${esc(p2Words.steady)}</p>`;
    const p2RecentMatches=completedMatches.slice(0,5);
    const p2RecentList=p2RecentMatches.length?p2RecentMatches.map((m:any)=>`<article class="commission-p2-fixture"><span class="commission-p2-fixture-date">${dateText(m.date)}</span><div><strong>${matchLink(m.fixture_id,`${m.home||"?"} × ${m.away||"?"}`)}</strong><small>${esc(m.competition||"")}</small></div><strong class="commission-p2-score">${m.home_score!=null&&m.away_score!=null?`${num(m.home_score)}–${num(m.away_score)}`:"N/D"}</strong><small class="commission-p2-fixture-source">${esc(m.detailed_stats_available?p2Words.recentStatus:p2Words.basicStatus)}</small></article>`).join(""):`<p class="muted commission-p2-empty">${esc(p2Words.noRecent)}</p>`;
    const p2PositionGroups=(d.position_comparisons||[]).filter((item:any)=>Number(item.minutes||0)>0).sort((a:any,b:any)=>Number(b.minutes)-Number(a.minutes)).slice(0,6);
    const p2ObservedGroups=(d.function_comparisons||[]).filter((item:any)=>Number(item.minutes||0)>0).sort((a:any,b:any)=>Number(b.minutes)-Number(a.minutes)).slice(0,6);
    const p2ComparisonRows=(items:any[])=>{
        const maxMinutes=Math.max(1,...items.map((item:any)=>Number(item.minutes||0)));
        return items.length?items.map((item:any)=>`<article class="commission-p2-position"><div><strong>${esc(item.position||"N/D")}</strong><small>${num(item.matches)} jogos · ${num(item.minutes)} ${esc(p2Words.min)} · ${esc(item.sample?.label||"N/D")}</small></div><div class="commission-p2-position-value"><strong>${item.average_rating==null?"N/D":num(item.average_rating,2)}</strong><small>${esc(p2Words.rating)}</small></div><div class="commission-p2-position-bar"><i style="width:${Math.max(0,Math.min(100,Number(item.minutes||0)*100/maxMinutes)).toFixed(1)}%"></i></div></article>`).join("") : `<p class="muted commission-p2-empty">${esc(p2Words.noCompare)}</p>`;
    };
    const p2ReviewFlag=!!cached.review_required;
    const p2SummaryState=reportState==="ready"||reportState==="stale";
    const p2ReportReady=p2SummaryState?reportSummary:`<p class="muted">${esc(p2Words.hint)}</p>`;
    const p2Coverage = `<section class="grid metrics analysis-metrics">${metric("Players on squad",num(coverage.squad_players),"selected snapshot")}${metric("With match ratings",num(coverage.players_with_performances),"player level")}${metric("MatchStats coverage",`${num(coverage.detailed_matches)} / ${num(coverage.completed_team_matches)}`,`${coverage.detailed_match_coverage_pct==null?"N/D":num(coverage.detailed_match_coverage_pct,1)+" %"} completed team matches`)}${metric("MatchStats player rows",num(coverage.detailed_player_rows),"complete linked exports")}</section>`;


    return `<div class="commission-p2">
      <header class="commission-p2-hero card"><div class="commission-p2-hero-copy"><span class="commission-p2-eyebrow">${esc(p2Words.overview)} · ${esc(d.selectedSeasonLabel||"")}</span><h2>${esc(d.managed_team_name||identity.team_name||"Equipe selecionada")}</h2><p>${identity.style_sample_sufficient?"Leitura estatística de indicadores observados na temporada. A IA interpreta o contexto e informa as limitações de cada conclusão.":esc(identity.sample_note||"Amostra insuficiente para caracterizar o desempenho coletivo com segurança.")}</p></div><div class="commission-p2-hero-meta"><span class="commission-p2-state">${esc(p2Words.sample)}</span><strong>${num(identity.detailed_matches)} <small>/ ${num(identity.completed_matches)}</small></strong><span>${identity.coverage_pct==null?"N/D":num(identity.coverage_pct,1)+" %"} ${esc(p2Words.coverage.toLowerCase())}</span></div></header>
      ${p2MetricsPanel}
      <div class="commission-p2-main"><div class="commission-p2-left">
        <section class="card commission-p2-signal-panel"><header class="card-header"><div><h2>${esc(p2Words.form)}</h2><p>${esc(p2Words.formNote)}</p></div><span>${num(p2UsablePlayers.length)} ${esc(p2Words.comparable)}</span></header><div class="commission-p2-form-columns"><section class="commission-p2-form-group positive"><h3>${esc(p2Words.up)}</h3>${p2FormRows(p2Rising)}</section><section class="commission-p2-form-group negative"><h3>${esc(p2Words.down)}</h3>${p2FormRows(p2Falling)}</section></div></section>
        <section class="card commission-p2-recent"><header class="card-header"><div><h2>${esc(p2Words.recent)}</h2><p>${esc(p2Words.recentNote)}</p></div></header><div class="commission-p2-fixtures">${p2RecentList}</div></section>
      </div><div class="commission-p2-right">
        <section class="card commission-p2-ai"><header class="card-header"><div><h2>${esc(p2Words.insights)}</h2><p>${esc(p2Words.insightsNote)}</p></div><span class="status-badge ${reportState==="ready"?"good":"amber"}">${esc(reportState)}</span></header><div class="card-body">${reportState==="stale"?`<p class="commission-p2-ai-warning">${esc(p2Words.notReady)}</p>`:""}${p2ReviewFlag?`<p class="commission-p2-ai-warning">${esc(p2Words.review)}</p>`:""}<div data-commission-report-output data-report-slot="commission-team" class="commission-report-output" aria-live="polite">${p2ReportReady}</div><button class="button primary" data-commission-report data-report-target="commission-team" data-mode="team_identity" data-snapshot-id="${Number(d.snapshot_id)}" data-force-refresh="${reportState==="ready"?"1":"0"}">${reportState==="ready"?esc(p2Words.action):esc(p2Words.generate)}</button></div></section>
      </div></div>
      <section class="card commission-p2-position-section"><header class="card-header"><div><h2>${esc(p2Words.comparisons)}</h2><p>${esc(p2Words.compNote)}</p></div></header><div class="commission-p2-position-columns"><section><h3>${esc(p2Words.pos)}</h3>${p2ComparisonRows(p2PositionGroups)}</section><section><h3>${esc(p2Words.observed)}</h3>${p2ComparisonRows(p2ObservedGroups)}</section></div></section>
      <details class="commission-p2-secondary"><summary>${esc(p2Words.details)}</summary><section class="card"><header class="card-header"><div><h2>${esc(p2Words.details)}</h2><p>${esc(p2Words.detailsNote)}</p></div></header><div class="card-body commission-profile-grid">${profileRows||`<p class="muted">Ainda não há pelo menos cinco partidas por perfil comparável.</p>`}</div><p class="data-note">Comparação por volume de finalizações do adversário e resultado registrado. Relação observada não comprova causa nem define tática.</p></section></details>
      <details class="commission-advanced"><summary>Tabelas completas, comparações detalhadas e ferramentas sob demanda</summary><div class="commission-advanced-body"><section class="card"><header class="card-header"><h2>Professional squad · ${esc(d.managed_team_name || "selected career")}</h2><span>${esc(d.selectedSeasonLabel || "snapshot data")}</span></header>${rows ? table([{label:"Player"},{label:"Pos.",cls:"center"},{label:"Hierarchy"},{label:"Min",cls:"num"},{label:"Season rating",cls:"num"},{label:"Last five",cls:"num"},{label:"Sample"},{label:"NPK G / A",cls:"num"},{label:"NPK-xG / xA",cls:"num"},{label:"Shots",cls:"num"},{label:"Pass accuracy",cls:"num"},{label:"Tackles / Int.",cls:"num"},{label:"Blocks / clearances",cls:"num"},{label:"Saves / conceded",cls:"num"},{label:"Form"},{label:"Commission note"}], rows) : '<div class="card-body muted">No professional match ratings are recorded for this snapshot.</div>'}</section><section class="grid two-col"><section class="card"><header class="card-header"><h2>Position comparison · registered role</h2></header>${posRows?table([{label:"Position"},{label:"Players",cls:"num"},{label:"Match rows",cls:"num"},{label:"Min",cls:"num"},{label:"Rating",cls:"num"},{label:"NPK G / 90",cls:"num"},{label:"xG / 90",cls:"num"},{label:"Sample"}],posRows):'<div class="card-body muted">No comparable MatchStats samples.</div>'}</section><section class="card"><header class="card-header"><h2>Observed function comparison</h2></header>${fnRows?table([{label:"Position"},{label:"Players",cls:"num"},{label:"Match rows",cls:"num"},{label:"Min",cls:"num"},{label:"Rating",cls:"num"},{label:"NPK G / 90",cls:"num"},{label:"Sample"}],fnRows):'<div class="card-body muted">N/D — no reliable observed match position.</div>'}</section></section><section class="card pad commission-studio"><div class="card-title-row"><div><h3 class="card-title">Report on demand</h3><p class="chart-note">Match, player and upcoming-fixture reports are saved by career and source facts, then reused when those facts are unchanged.</p></div><span class="status-badge good">Local Ollama</span></div><div class="commission-studio-controls"><label class="page-filter"><span>Analysis</span><select data-commission-mode><option value="match">Review completed match</option><option value="player">Review a player</option><option value="next_match">Prepare upcoming match</option></select></label><label class="page-filter" data-commission-fixture-wrap><span>Match</span><select data-commission-fixture>${reportMatchOptions||'<option value="">No completed matches</option>'}</select></label><label class="page-filter" data-commission-next-wrap hidden><span>Upcoming fixture</span><select data-commission-next-fixture>${reportNextOptions||'<option value="">No upcoming fixture</option>'}</select></label><label class="page-filter" data-commission-player-wrap hidden><span>Player</span><select data-commission-player>${reportPlayerOptions||'<option value="">No professional players</option>'}</select></label><button class="button" data-commission-report data-snapshot-id="${num(d.snapshot_id)}">Generate report</button></div><div data-commission-report-output class="commission-report-output" aria-live="polite"></div></section><div class="grid two-col analysis-grid"><section class="card pad"><h3 class="card-title">Sample rules</h3><p class="chart-note">Usable: 300+ minutes and 3+ appearances. Reliable: 450+ minutes and 5+ appearances. Form uses up to five valid appearances weighted by minutes. Hierarchy stays N/D when not recorded.</p></section><section class="card pad"><h3 class="card-title">Coverage</h3><p class="chart-note">${esc(coverage.detailed_metric_scope||"MatchStats coverage unavailable.")} ${coverage.detailed_match_coverage_pct==null?"N/D":`${num(coverage.detailed_match_coverage_pct,1)} %`} (${num(coverage.detailed_matches)} of ${num(coverage.completed_team_matches)} completed matches). Missing metrics stay N/D; youth 5x5 remains separate.</p></section></div></div></details>
      <details class="commission-p2-secondary commission-p2-process"><summary>Processamento histórico e ferramentas de auditoria</summary><div class="commission-p2-process-body">${retroactiveBatch}<section class="card pad"><h3 class="card-title">${esc(p2Words.method)}</h3>${p2Coverage}<div class="commission-p2-audit-metrics"><div>Passes / jogo: <b>${tm.passes_per_match==null?"N/D":num(tm.passes_per_match,1)}</b></div><div>Dribles completos / jogo: <b>${tm.dribbles_completed_per_match==null?"N/D":num(tm.dribbles_completed_per_match,1)}</b></div><div>Cruzamentos tentados / jogo: <b>${tm.crosses_attempted_per_match==null?"N/D":num(tm.crosses_attempted_per_match,1)}</b></div><div>Passes em profundidade / jogo: <b>${tm.through_passes_per_match==null?"N/D":num(tm.through_passes_per_match,1)}</b></div><div>Interceptações / jogo: <b>${tm.interceptions_per_match==null?"N/D":num(tm.interceptions_per_match,1)}</b></div><div>Cobertura detalhada: <b>${coverage.detailed_match_coverage_pct==null?"N/D":num(coverage.detailed_match_coverage_pct,1)+" %"}</b></div></div><p class="data-note">Posse percentual, pressão, altura da linha e formação tática ficam indisponíveis se não exportadas. Nenhuma inferência é apresentada como observação direta.</p></section></div></details>
    </div>`;

}


function analysisMatchSummary(mi:any):string {
    if(!mi?.available) return `<section class="card pad"><div class="card-title-row"><h3 class="card-title">FC26 match data</h3>${statusBadge("No detailed matches yet","amber")}</div><p class="chart-note">Once validated match exporter data is linked, xG/xA, shots, passing, duels and other performance metrics appear here.</p></section>`;
    const f=mi.team?.for||{},a=mi.team?.against||{};
    const coverage=mi.coveragePct==null?`${num(mi.matchesCovered)} detailed matches`:`${num(mi.matchesCovered)} / ${num(mi.totalCompletedMatches)} matches · ${num(mi.coveragePct,0)} %`;
    return `<section class="card pad"><div class="card-title-row"><div><h3 class="card-title">FC26 match data</h3><span>${coverage}</span></div>${statusBadge("Direct FC26 data","good")}</div><div class="grid metrics compact">${metric(f.expected_goals_derived_per_match!=null?"Team xG / match":"NPK-xG / match",`${num(f.expected_goals_derived_per_match??f.npk_expected_goals_per_match,2)} : ${num(a.expected_goals_derived_per_match??a.npk_expected_goals_per_match,2)}`,`${num((Number(f.expected_goals_derived_per_match??f.npk_expected_goals_per_match)||0)-(Number(a.expected_goals_derived_per_match??a.npk_expected_goals_per_match)||0),2)} difference`,"green")}${metric("xA / match",`${num(f.expected_assists_per_match,2)} : ${num(a.expected_assists_per_match,2)}`,"for : against","blue")}${metric("Shots / match",`${num(f.shots_per_match,1)} : ${num(a.shots_per_match,1)}`,`xG/shot ${num(f.xg_per_shot,3)} : ${num(a.xg_per_shot,3)}`)}${metric("Pass accuracy",`${num(f.pass_accuracy_pct_derived,1)} %`,`${num(a.pass_accuracy_pct_derived,1)} % opponent`)}${metric("Possession balance / match",`${num(f.possession_won_per_match,1)} / ${num(f.possession_lost_per_match,1)}`,`opponent ${num(a.possession_won_per_match,1)} / ${num(a.possession_lost_per_match,1)}`)}${metric("Duels",f.combined_duel_success_pct==null?"–":`${num(f.combined_duel_success_pct,1)} %`,a.combined_duel_success_pct==null?"–":`${num(a.combined_duel_success_pct,1)} % opponent`)}</div></section>`;
}
function analysisMatchIntelligence(d:any):string {
    const mi=d.matchIntelligence||{};
    if(!mi.available) return `<div class="grid">${analysisMatchSummary(mi)}</div>`;
    const f=mi.team?.for||{},a=mi.team?.against||{}, players=(mi.players||[]).slice();
    const leaders=[
      ["NPK-xG","npk_expected_goals",2],["xA","expected_assists",2],["Key passes","key_passes",0],["Possession won","possession_won",0],["Interceptions","interceptions",0],["Avg. rating","average_game_rating",2]
    ];
    const trendPoints=(mi.trends||[]).map((t:any)=>({...t,season_label:dateText(t.date)}));
    const venue=mi.splits?.venue||{}, home=venue.home||{}, away=venue.away||{};
    const competitionSplits=mi.splits?.competitions||[];
    const competitionSplitTable=competitionSplits.length ? `<section class="card"><header class="card-header"><div><h2>Competition profiles</h2><p>Per-match values rather than raw totals</p></div><span>${num(competitionSplits.length)} competitions</span></header>${table([{label:"Competition"},{label:"Matches",cls:"num"},{label:"NPK-xG / match",cls:"num"},{label:"Shots / match",cls:"num"},{label:"xG / shot",cls:"num"},{label:"Duels",cls:"num"}],competitionSplits.map((c:any)=>`<tr><td><strong>${esc(c.competitionName||"–")}</strong></td><td class="num">${num(c.matches)}</td><td class="num">${num(c.for?.npk_expected_goals_per_match,2)} : ${num(c.against?.npk_expected_goals_per_match,2)}</td><td class="num">${num(c.for?.shots_per_match,1)} : ${num(c.against?.shots_per_match,1)}</td><td class="num">${num(c.for?.xg_per_shot,3)} : ${num(c.against?.xg_per_shot,3)}</td><td class="num">${c.for?.combined_duel_success_pct==null?"–":`${num(c.for.combined_duel_success_pct,1)} %`}</td></tr>`))}</section>` : "";
    return `<div class="grid">${analysisMatchSummary(mi)}<div class="grid two-col analysis-grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">NPK-xG per match</h3><span>for / against</span></div>${simpleBarChart(trendPoints,[{key:"npkXgFor",label:"NPK-xG for"},{key:"npkXgAgainst",label:"NPK-xG against"}])}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Five-match underlying trend</h3><span>rolling NPK-xG balance</span></div>${simpleBarChart(trendPoints,[{key:"rolling5XgDiff",label:"Avg. NPK-xG difference (5)"}])}</section></div>
      <section class="card"><header class="card-header"><div><h2>Team profile from detailed data</h2><p>Totals plus reliable per-match and efficiency metrics</p></div></header><div class="card-body">${detailedAggregateGroups(f)}<div class="grid metrics compact" style="margin-top:12px">${metric("Home",num(home.matches),`${num(home.for?.npk_expected_goals_per_match,2)} NPK-xG/match`)}${metric("Away",num(away.matches),`${num(away.for?.npk_expected_goals_per_match,2)} NPK-xG/match`)}${metric("Chance quality",num(f.xg_per_shot,3),"NPK-xG per shot","green")}${metric("Pass accuracy under pressure",f.pressure_pass_accuracy_pct==null?"–":`${num(f.pressure_pass_accuracy_pct,1)} %`,"passes under pressure")}</div></div><div class="data-note">Opponent comparison: ${num(a.npk_expected_goals_per_match,2)} NPK-xG/match · ${num(a.expected_assists_per_match,2)} xA/match · ${num(a.shots_per_match,1)} shots/match. ${esc(mi.xgNote||"")}</div></section>
      <section class="card"><header class="card-header"><h2>Detailed-data leaders</h2><span>only matches with detailed FC26 imports</span></header><div class="match-leader-grid">${leaders.map(([label,key,digits]:any)=>{const rows=players.filter((p:any)=>p.stats?.[key]!=null).sort((x:any,y:any)=>(Number(y.stats[key])||0)-(Number(x.stats[key])||0)).slice(0,5);return `<div class="match-leader-card"><h4>${esc(label)}</h4>${rows.map((p:any,i:number)=>`<div><span>${num(i+1)}. ${p.playerEaId?playerLink(p.playerEaId,p.displayName):esc(p.displayName||"–")}</span><strong>${num(p.stats[key],digits)}</strong></div>`).join("")||'<span class="muted">–</span>'}</div>`;}).join("")}</div></section>
      ${competitionSplitTable}
      <section class="card"><header class="card-header"><h2>Match-by-match profile</h2><span>${num(mi.matchesCovered)} matches</span></header>${table([{label:"Date"},{label:"Match"},{label:"Competition"},{label:"NPK-xG",cls:"num"},{label:"xA",cls:"num"},{label:"Shots",cls:"num"},{label:"5-match xG balance",cls:"num"}],(mi.trends||[]).slice().reverse().map((t:any)=>`<tr><td>${dateText(t.date)}</td><td>${matchLink(t.fixtureId,`${t.homeTeamName||"?"} – ${t.awayTeamName||"?"}`)}<small class="table-subline">${t.venue==="home"?"Home":"Away"}</small></td><td>${esc(t.competitionName||"–")}</td><td class="num">${num(t.npkXgFor,2)} : ${num(t.npkXgAgainst,2)}</td><td class="num">${num(t.xAFor,2)} : ${num(t.xAAgainst,2)}</td><td class="num">${num(t.shotsFor)} : ${num(t.shotsAgainst)}</td><td class="num">${Number(t.rolling5XgDiff)>=0?"+":""}${num(t.rolling5XgDiff,2)}</td></tr>`))}</section></div>`;
}
function analysisOverview(d: any, placementMetric: any): string {
    const m = d.metrics || {};
    const overview = d.seasonOverview || {};
    const competitionRows = overview.competitions || [];
    const leaderRows = overview.leaders || [];
    const seasonTable = d.leagueHistory?.length ? table([
      { label: "Season" }, { label: "League" }, { label: "Position", cls: "center" }, { label: "League movement" }, { label: "Source" }
    ], d.leagueHistory.map((row: any) => `<tr><td>${esc(row.season_label)}${row.is_current ? `<small class="table-subline">current season</small>` : ""}</td><td>${esc(row.league_name)}</td><td class="center"><strong>${esc(row.position_display || "–")}</strong>${row.result_status === "running" && row.position_source_label ? `<small class="table-subline">${esc(row.position_source_label)}</small>` : ""}</td><td>${row.movement === "promotion" ? statusBadge("Promotion", "good") : row.movement === "relegation" ? statusBadge("Relegation", "bad") : row.movement === "same" ? statusBadge("same league") : row.movement === "first" ? statusBadge("Start") : statusBadge("unknown")}</td><td>${statusBadge(row.source_label, row.source === "manual" ? "good" : "")}</td></tr>`)) : '<div class="card-body"><span class="muted">No league history available yet.</span></div>';
    return `<div class="grid metrics analysis-metrics">${metric("Matches", num(m.matches), `${num(m.wins)} W · ${num(m.draws)} D · ${num(m.losses)} L`, "green")}${metric("Goal balance", `${num(m.goals_for)}:${num(m.goals_against)}`, `${num((Number(m.goals_for)||0)-(Number(m.goals_against)||0))} difference`, "blue")}${metric(placementMetric.title, placementMetric.value, placementMetric.sub)}${metric("Titles", num(m.titles), "confirmed competition wins", "amber")}${metric("Players", num(m.players_used), "with appearances")}${metric("Transfers / Loans", `${num(m.transfers)} / ${num(m.loans)}`, "managed club")}</div>
      <div class="grid two-col analysis-grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">League path</h3><span>with season position</span></div>${leaguePositionChart(d.leagueHistory || [])}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Transfer activity</h3><span>managed club</span></div>${simpleBarChart(d.transferActivity || [], [{key:"incoming",label:"Arrivals"},{key:"outgoing",label:"Departures"},{key:"loans_in",label:"Loans in"},{key:"loans_out",label:"Loans out"}])}</section></div>
      <div class="grid split-65"><div class="grid"><section class="card"><header class="card-header"><h2>Season results</h2><span>${num((d.leagueHistory || []).length)} seasons</span></header>${seasonTable}</section>
      <section class="card"><header class="card-header"><h2>${Number(d.selectedSeasonIndex) === -1 ? "Transfer activity by season" : "Season overview"}</h2><span>${esc(d.selectedSeasonLabel)}</span></header>${Number(d.selectedSeasonIndex) === -1 ? table([{label:"Season"},{label:"Arrivals",cls:"num"},{label:"Departures",cls:"num"},{label:"Loans in",cls:"num"},{label:"Loans out",cls:"num"},{label:"Unknown fees",cls:"num"}], (d.transferActivity || []).map((r:any)=>`<tr><td>${esc(r.season_label)}</td><td class="num">${num(r.incoming)}</td><td class="num">${num(r.outgoing)}</td><td class="num">${num(r.loans_in)}</td><td class="num">${num(r.loans_out)}</td><td class="num">${num(r.unknown_fees)}</td></tr>`)) : `<div class="card-body grid two-col"><div><h4>Competitions</h4><div class="list">${competitionRows.map((c:any)=>`<div class="list-row"><div class="list-main"><strong>${c.competition_object_id ? competitionLink(c.competition_object_id,c.competition_name) : esc(c.competition_name)}</strong><small>${c.result_text || `${num(c.completed)} of ${num(c.matches)} matches`}</small></div>${c.final_position ? statusBadge(`#${num(c.final_position)}`) : ""}</div>`).join("") || '<span class="muted">No competitions recorded.</span>'}</div></div><div><h4>Top players</h4><div class="list">${leaderRows.map((p:any)=>`<div class="list-row"><div class="list-main">${p.player_ea_id ? playerLink(p.player_ea_id,p.display_name) : esc(p.display_name)}<small>${num(p.appearances)} appearances · ${ratingValue(p.average_rating,true)}</small></div><div class="list-value"><strong>${num(p.goals)} G</strong><small>${num(p.assists)} A</small></div></div>`).join("") || '<span class="muted">No player statistics.</span>'}</div></div></div>`}</section></div><aside class="grid">${qualityPanel(d.quality)}<section class="card pad"><h3 class="card-title">Data sources</h3><div class="source-legend"><span>${statusBadge("Imported")}</span><span>${statusBadge("Derived", "blue")}</span><span>${statusBadge("Manual", "good")}</span><p>Missing values are not estimated. A current season is considered complete only after a later season snapshot.</p></div></section></aside></div>${analysisMatchSummary(d.matchIntelligence)}`;
}

function analysisSquad(d: any): string {
    const m = d.metrics || {};
    const squadAnalysis = d.squadAnalysis || {};
    const squadSummary = squadAnalysis.summary || {};
    const positionRows = squadAnalysis.positionBalance || [];
    const performanceRows = squadAnalysis.performanceLeaders || [];
    return `<div class="grid metrics analysis-metrics">${metric("Squad size", num(m.squad_count), "latest snapshot in the period")}${metric("Avg. OVR", num(m.average_overall, 1), "Squad strength", "green")}${metric("Avg. age", num(m.average_age, 1), "squad average", "blue")}${metric("Avg. POT", num(squadSummary.average_potential, 1), "development potential", "amber")}${metric("Players used", num(squadSummary.performance_player_count), d.selectedSeasonLabel)}</div>
      <div class="grid two-col analysis-grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Squad strength</h3><span>by snapshot</span></div>${lineChart(d.squadTrend || [], ["average_overall"], {decimals:1, ariaLabel:"Durchschnittliche Squad strength", unit:" OVR"})}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Average age</h3><span>by snapshot</span></div>${lineChart(d.squadTrend || [], ["average_age"], {decimals:1, ariaLabel:"Average age", unit:" J."})}</section></div>
      <div class="grid two-col analysis-grid"><section class="card"><header class="card-header"><h2>Squad balance</h2><span>${num(squadSummary.squad_count)} players · Avg. POT ${num(squadSummary.average_potential,1)}</span></header>${positionRows.length ? table([{label:"Position group"},{label:"Players",cls:"num"},{label:"Avg. OVR",cls:"num"},{label:"Avg. POT",cls:"num"},{label:"Avg. age",cls:"num"}], positionRows.map((r:any)=>`<tr><td><strong>${esc(r.group)}</strong></td><td class="num">${num(r.count)}</td><td class="num">${num(r.average_overall,1)}</td><td class="num">${num(r.average_potential,1)}</td><td class="num">${num(r.average_age,1)}</td></tr>`)) : '<div class="card-body"><span class="muted">No squad snapshot is available for this period.</span></div>'}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Age structure</h3><span>${squadSummary.youngest_age != null ? `${num(squadSummary.youngest_age)}–${num(squadSummary.oldest_age)} years` : "no squad snapshot"}</span></div>${horizontalBars(squadAnalysis.ageStructure || [])}</section></div>
      <div class="grid two-col analysis-grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Appearance distribution</h3><span>${num(squadSummary.performance_player_count)} players used</span></div>${horizontalBars(squadAnalysis.appearanceDistribution || [])}<p class="chart-note">${esc(squadAnalysis.usageDefinition || "")}</p></section><section class="card"><header class="card-header"><h2>Top performers</h2><span>selected period</span></header>${performanceRows.length ? table([{label:"Player"},{label:"Pos.",cls:"center"},{label:"Matches",cls:"num"},{label:"Goals",cls:"num"},{label:"Assists",cls:"num"},{label:"G+A",cls:"num"},{label:"Avg. rating",cls:"num"}], performanceRows.map((p:any)=>`<tr><td>${p.player_ea_id ? playerLink(p.player_ea_id,p.display_name) : esc(p.display_name)}</td><td class="center">${positionBadge(p.primary_position)}</td><td class="num">${num(p.appearances)}</td><td class="num">${num(p.goals)}</td><td class="num">${num(p.assists)}</td><td class="num"><strong>${num(p.goal_contributions)}</strong></td><td class="num">${ratingValue(p.average_rating,true)}</td></tr>`)) : '<div class="card-body"><span class="muted">No player statistics in the selected period.</span></div>'}</section></div>${analysisMatchSummary(d.matchIntelligence)}`;
}

function analysisSeasons(d: any): string {
    const rows = d.seasonComparison || [], detailBySeason=new Map((d.matchIntelligence?.bySeason||[]).map((x:any)=>[Number(x.seasonIndex),x]));
    const seasonRows = rows.map((r:any)=>{const md:any=detailBySeason.get(Number(r.season_index)),f=md?.for||{},a=md?.against||{};return `<tr><td><strong>${esc(r.season_label)}</strong>${r.is_current ? '<small class="table-subline">current</small>' : ""}</td><td>${esc(r.league_name || "–")}<small class="table-subline">${esc(r.position_display || "–")}</small></td><td class="num">${num(r.matches)}</td><td class="num">${num(r.wins)} / ${num(r.draws)} / ${num(r.losses)}</td><td class="num">${num(r.goals_for)}:${num(r.goals_against)}</td><td class="num">${num(r.goal_difference)}</td><td class="num">${md?`${num(f.npk_expected_goals,2)} : ${num(a.npk_expected_goals,2)}`:"–"}</td><td class="num">${md?`${num(f.expected_assists,2)} : ${num(a.expected_assists,2)}`:"–"}</td><td class="num">${md?num(md.matchesCovered):"–"}</td><td class="num">${num(r.players_used)}</td><td>${r.top_scorer_name ? (r.top_scorer_id ? playerLink(r.top_scorer_id,r.top_scorer_name) : esc(r.top_scorer_name)) + ` · ${num(r.top_scorer_goals)} G` : "–"}</td><td class="num">${num(r.average_overall,1)}</td><td class="num">${num(r.average_age,1)}</td><td class="num">${num(r.transfers)} / ${num(r.loans)}</td></tr>`;});
    const detailRows=(d.matchIntelligence?.bySeason||[]).map((x:any)=>({season_label:(rows.find((r:any)=>Number(r.season_index)===Number(x.seasonIndex))||{}).season_label||`Season ${num(Number(x.seasonIndex)+1)}`,npkXgFor:x.for?.npk_expected_goals,npkXgAgainst:x.against?.npk_expected_goals}));
    return `<div class="grid two-col analysis-grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Results by season</h3><span>Wins, draws and losses</span></div>${simpleBarChart(rows, [{key:"wins",label:"Wins"},{key:"draws",label:"Draws"},{key:"losses",label:"Losses"}])}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Goals by season</h3><span>scored and conceded</span></div>${simpleBarChart(rows, [{key:"goals_for",label:"Goals"},{key:"goals_against",label:"Goals against"}])}</section></div>
      ${detailRows.length?`<section class="card pad"><div class="card-title-row"><h3 class="card-title">NPK-xG by season</h3><span>detailed FC26 matches only</span></div>${simpleBarChart(detailRows,[{key:"npkXgFor",label:"NPK-xG for"},{key:"npkXgAgainst",label:"NPK-xG against"}])}</section>`:""}
      <section class="card"><header class="card-header"><h2>Season comparison</h2><span>${num(rows.length)} seasons</span></header>${rows.length ? table([{label:"Season"},{label:"League / position"},{label:"Matches",cls:"num"},{label:"W / D / L",cls:"num"},{label:"Goals",cls:"num"},{label:"Diff.",cls:"num"},{label:"NPK-xG F:A",cls:"num"},{label:"xA F:A",cls:"num"},{label:"Detailed",cls:"num"},{label:"Players",cls:"num"},{label:"Top scorer"},{label:"Avg. OVR",cls:"num"},{label:"Avg. age",cls:"num"},{label:"Tr. / L.",cls:"num"}], seasonRows, "season-comparison-table") : '<div class="card-body"><span class="muted">No comparable season data available yet.</span></div>'}</section>
      <p class="data-note">NPK-xG/xA comes only from clearly linked detailed FC26 match exports. Manually entered player statistics are summed across all competitions in the season; snapshot and manual values are not double-counted.</p>`;
}



let currentSeasonReportData: any = null;

function seasonReportPicker(options: any[], selected: number): string {
    return `<label class="page-filter"><span>Season</span><select data-season-report-season>${options.map((option:any)=>`<option value="${option.season_index}" ${Number(option.season_index)===Number(selected)?"selected":""}>${esc(option.label)}${option.is_current ? " · current" : ""}</option>`).join("")}</select></label>`;
}

function seasonReportTabs(active: string): string {
    const tabs = [["overview","Overview"],["competitions","Competitions"],["squad","Squad & performance"],["transfers","Transfers"],["awards","Awards"],["quality","Data quality"]];
    return `<div class="page-tabs season-report-tabs">${tabs.map(([key,label])=>`<button class="${active===key?"active":""}" data-season-report-tab="${key}">${label}</button>`).join("")}</div>`;
}

function awardPortrait(award: any): string {
    return playerPortrait(award.media, award.display_name, "season-award-portrait");
}

function automaticAwardCards(report: any): string {
    const awards = report?.awards || [];
    if (!report?.awards_available) return `<div class="award-lock"><strong>Awards are locked</strong><span>${esc(report?.completion?.label || "The season must be completed first.")}</span></div>`;
    if (!awards.length) return '<div class="muted">Not enough season statistics are available for automatic awards yet.</div>';
    return `<div class="season-award-grid fancy">${awards.map((award:any)=>{
        const payload=encodeURIComponent(JSON.stringify(award));
        return `<article class="season-award-card automatic">${awardPortrait(award)}<div class="season-award-copy"><span>Tracker evaluation · ${esc(award.label)}</span><strong>${award.player_ea_id ? playerLink(award.player_ea_id,award.display_name) : esc(award.display_name || "–")}</strong><b>${esc(award.value || "–")}</b><small>${esc(award.rule || "")}</small><button class="button tiny" data-season-award-copy="${payload}">Use as manager award</button></div></article>`;
    }).join("")}</div>`;
}

function managerAwardCards(report: any): string {
    const awards = report?.manual?.awards || [];
    if (!report?.awards_available) return `<div class="award-lock"><strong>Manager awards are locked</strong><span>${esc(report?.completion?.label || "The season must be completed first.")}</span></div>`;
    if (!awards.length) return '<div class="muted">No custom season awards have been assigned yet.</div>';
    return `<div class="season-award-grid fancy">${awards.map((award:any)=>{
        const payload=encodeURIComponent(JSON.stringify(award));
        const transfer = award.from_team_name || award.to_team_name ? `<small class="award-transfer">${esc(award.from_team_name || "–")} → ${esc(award.to_team_name || "–")}${award.fee != null ? ` · ${money(award.fee)}` : ""}</small>` : "";
        return `<article class="season-award-card manager">${awardPortrait(award)}<div class="season-award-copy"><span>Manager award · ${esc(award.award_label)}</span><strong>${award.player_ea_id ? playerLink(award.player_ea_id,award.display_name) : esc(award.display_name || "–")}</strong>${transfer}${award.reason ? `<p>${esc(award.reason)}</p>` : ""}<div class="row-actions"><button class="button tiny" data-season-award-edit="${payload}">Edit</button><button class="button tiny danger" data-season-award-delete="${award.id}">Delete</button></div></div></article>`;
    }).join("")}</div>`;
}

function seasonAwardEditor(report: any): string {
    const manual = report?.manual || {}, players = manual.players || [], categories = manual.categories || [], transfers = manual.transfers || [];
    if (!report?.awards_available) return `<section class="card pad award-editor-locked"><h3 class="card-title">Custom awards</h3><p>Season awards can be assigned only after the final match of the season.</p><small>${esc(report?.completion?.label || "Season end not confirmed")}</small></section>`;
    return `<form class="card pad season-award-editor" data-season-award-form><input type="hidden" name="id"><div class="card-title-row"><h3 class="card-title">Assign custom award</h3><span>does not change the Tracker evaluation</span></div><div class="form-grid three"><label><span>Category</span><select name="awardKey">${categories.map((c:any)=>`<option value="${esc(c.key)}">${esc(c.label)}</option>`).join("")}</select></label><label><span>Custom award name</span><input name="awardLabel" placeholder="only for Custom award"></label><label><span>Player</span><select name="playerEaId" data-season-award-player><option value="">Choose player</option>${players.map((p:any)=>`<option value="${p.player_ea_id ?? ""}" data-name="${esc(p.display_name)}">${esc(p.display_name)} · ${pos(p.primary_position)} · ${num(p.appearances)} apps</option>`).join("")}</select></label><label><span>Player name</span><input name="displayName" data-season-award-name required placeholder="Player name"></label><label><span>Related manual transfer</span><select name="relatedTransactionId"><option value="">None</option>${transfers.filter((t:any)=>t.id).map((t:any)=>`<option value="${t.id}">${esc(t.display_name)} · ${esc(t.from_team_name || "–")} → ${esc(t.to_team_name || "–")}${t.fee != null ? ` · ${money(t.fee)}` : ""}</option>`).join("")}</select></label><label class="span-3"><span>Reason / note</span><textarea name="reason" rows="3" placeholder="Why does this player receive the award?"></textarea></label></div><div class="row-actions"><button class="button primary" type="submit">Save award</button><button class="button" type="reset">Clear form</button></div></form>`;
}

function seasonMovementRows(items: any[], type: "transfer" | "loan"): string {
    if (!items?.length) return '<span class="muted">No movements recorded.</span>';
    return `<div class="season-report-movements">${items.filter((item:any)=>item.direction !== "Global").map((item:any)=>{
        const fromId = type === "loan" ? item.parent_team_ea_id : item.from_team_ea_id;
        const fromName = type === "loan" ? item.parent_team_name : item.from_team_name;
        const toId = type === "loan" ? item.loan_team_ea_id : item.to_team_ea_id;
        const toName = type === "loan" ? item.loan_team_name : item.to_team_name;
        return `<div class="season-report-movement"><div><strong>${item.player_ea_id ? playerLink(item.player_ea_id,item.display_name) : esc(item.display_name || "–")}</strong><small>${dateText(item.date || item.first_observed_date)}</small></div><div class="season-report-route"><span>${fromId ? clubLink(fromId,fromName) : esc(fromName || "–")}</span><b>→</b><span>${toId ? clubLink(toId,toName) : esc(toName || "–")}</span></div><div><strong>${type === "transfer" ? (item.fee == null ? "Fee unknown" : money(item.fee)) : (item.loan_end_date ? `to ${dateText(item.loan_end_date)}` : "Loan")}</strong><small>${esc(item.source_label || "")}</small></div></div>`;
    }).join("")}</div>`;
}

function seasonReportOverview(d:any): string {
    const m=d.metrics||{}, overview=d.seasonOverview||{}, report=d.seasonReport||{}, league=overview.leagueFinish||{};
    return `<section class="card season-report-hero"><div><span>Season</span><h2>${esc(d.selectedSeasonLabel)}</h2><p>${esc(league.league_name || "League not recorded")} · ${esc(league.position_display || (report.is_current ? "current" : "Position unknown"))}</p>${league.position_source_label ? `<small>${esc(league.position_source_label)}</small>` : ""}</div><div class="season-report-score"><div><strong>${num(m.wins)}</strong><span>Wins</span></div><div><strong>${num(m.draws)}</strong><span>Draws</span></div><div><strong>${num(m.losses)}</strong><span>Losses</span></div></div><div><span>Goal balance</span><h2>${num(m.goals_for)}:${num(m.goals_against)}</h2><p>${num((Number(m.goals_for)||0)-(Number(m.goals_against)||0))} goal difference</p></div></section>
      <div class="grid metrics analysis-metrics">${metric("Matches",num(m.matches),`${num(m.players_used)} players used`,"green")}${metric("League position",esc(league.position_display || "–"),league.league_name || "League unknown")}${metric("Titles",num(m.titles),"confirmed competition wins","amber")}${metric("Transfers / Loans",`${num(m.transfers)} / ${num(m.loans)}`,"managed club")}${metric("Avg. squad OVR",num(m.average_overall,1),`Avg. age ${num(m.average_age,1)}`,"blue")}</div>
      <div class="grid two-col"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Season highlights</h3><span>from records</span></div>${recordCatalog(report.records || {})}</section><section class="card pad"><h3 class="card-title">Season review</h3><form data-season-report-note-form><textarea name="summaryNote" rows="8" placeholder="Your season review, turning points, objectives…">${esc(report.manual?.summaryNote || "")}</textarea><div class="row-actions"><button class="button primary" type="submit">Save note</button></div></form></section></div>${analysisMatchSummary(d.matchIntelligence)}`;
}

function seasonReportCompetitions(d:any): string {
    const competitions=d.seasonOverview?.competitions||[];
    return `<section class="card"><header class="card-header"><h2>Competitions</h2><span>${num(competitions.length)} entries</span></header>${competitions.length ? table([{label:"Competition"},{label:"Matches",cls:"num"},{label:"Result"}],competitions.map((c:any)=>`<tr><td>${c.competition_object_id ? competitionLink(c.competition_object_id,c.competition_name) : esc(c.competition_name || "–")}</td><td class="num">${num(c.completed)} / ${num(c.matches)}</td><td>${esc(c.result_text || (c.final_position ? `#${num(c.final_position)}` : "–"))}</td></tr>`)) : '<div class="card-body muted">No competitions recorded.</div>'}</section>`;
}

function seasonReportSquad(d:any): string {
    const leaders=d.squadAnalysis?.performanceLeaders||[], squad=d.squadAnalysis||{};
    return `<div class="grid"><section class="card"><header class="card-header"><h2>Top performers</h2><span>all competitions</span></header>${leaders.length ? table([{label:"Player"},{label:"Pos.",cls:"center"},{label:"Apps",cls:"num"},{label:"G",cls:"num"},{label:"A",cls:"num"},{label:"G+A",cls:"num"},{label:"Avg. rating",cls:"num"}],leaders.slice(0,20).map((p:any)=>`<tr><td>${p.player_ea_id ? playerLink(p.player_ea_id,p.display_name) : esc(p.display_name)}</td><td class="center">${positionBadge(p.primary_position)}</td><td class="num">${num(p.appearances)}</td><td class="num">${num(p.goals)}</td><td class="num">${num(p.assists)}</td><td class="num"><b>${num(p.goal_contributions)}</b></td><td class="num">${ratingValue(p.average_rating,true)}</td></tr>`)) : '<div class="card-body muted">No player statistics.</div>'}</section><div class="grid two-col"><section class="card pad"><h3 class="card-title">Squad balance</h3>${horizontalBars((squad.positionGroups||[]).map((r:any)=>({label:r.group,count:r.count,average_overall:r.average_overall})))}</section><section class="card pad"><h3 class="card-title">Age structure</h3>${horizontalBars(squad.ageGroups||[])}</section></div></div>`;
}

function seasonReportTransfers(d:any): string {
    const report=d.seasonReport||{}, overview=d.seasonOverview||{};
    return `<div class="grid two-col"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Transfers</h3><span>${num(report.transfer_count)}</span></div>${seasonMovementRows(overview.transfers||[],"transfer")}</section><section class="card pad"><div class="card-title-row"><h3 class="card-title">Loans</h3><span>${num(report.loan_count)}</span></div>${seasonMovementRows(overview.loans||[],"loan")}</section></div>`;
}

function seasonReportAwards(d:any): string {
    const report=d.seasonReport||{};
    return `<div class="grid"><section class="card pad"><div class="card-title-row"><h3 class="card-title">Manager awards</h3><span>custom</span></div>${managerAwardCards(report)}</section>${seasonAwardEditor(report)}<section class="card pad"><div class="card-title-row"><h3 class="card-title">Tracker evaluation</h3><span>rule-based</span></div>${automaticAwardCards(report)}</section></div>`;
}

function seasonReportQuality(d:any): string {
    return `<div class="grid two-col">${qualityPanel(d.quality)}<section class="card pad"><h3 class="card-title">Report rules</h3><p class="chart-note">${esc(d.seasonReport?.method_note || "The report uses available data only.")}</p><p class="chart-note">Manual awards remain separate from automatically calculated Tracker awards. Missing competitions, fees or historical statistics are not filled in.</p></section></div>`;
}

function downloadText(filename:string, text:string, type:string):void { const blob=new Blob([text],{type}); const url=URL.createObjectURL(blob); const a=document.createElement("a"); a.href=url; a.download=filename; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
function exportSeasonReportCsv():void { const d=currentSeasonReportData; if(!d)return; const m=d.metrics||{}, rows=[["Season",d.selectedSeasonLabel],["League",d.seasonOverview?.leagueFinish?.league_name||""],["Position",d.seasonOverview?.leagueFinish?.position_display||""],["Matches",m.matches],["Wins",m.wins],["Draws",m.draws],["Losses",m.losses],["Goals",m.goals_for],["Goals against",m.goals_against],["Players",m.players_used]]; const awards=(d.seasonReport?.manual?.awards||[]).map((a:any)=>[a.award_label,a.display_name,a.reason||""]); const csv=["Section;Value;Note",...rows.map((r:any)=>r.map((v:any)=>`"${String(v??"").replaceAll('"','""')}"`).join(";")),...awards.map((r:any)=>`"Award: ${String(r[0]).replaceAll('"','""')}";"${String(r[1]).replaceAll('"','""')}";"${String(r[2]).replaceAll('"','""')}"`)].join("\r\n"); downloadText(`Atlas_Season_Report_${d.selectedSeasonLabel.replace('/','-')}.csv`,`\ufeff${csv}`,"text/csv;charset=utf-8"); }
async function exportSeasonInfographic(format: "square" | "portrait" = "portrait"):Promise<void> {
    const d=currentSeasonReportData;if(!d)return;
    const canvas=document.createElement("canvas"), W=1080, H=format==="square"?1080:1350;
    canvas.width=W;canvas.height=H;const ctx=canvas.getContext("2d");if(!ctx)return;
    const m=d.metrics||{},league=d.seasonOverview?.leagueFinish||{},awards=d.seasonReport?.manual?.awards?.length?d.seasonReport.manual.awards:(d.seasonReport?.awards||[]);
    const grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,"#102c43");grad.addColorStop(1,"#07121f");ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
    ctx.fillStyle="#20df83";ctx.fillRect(64,64,12,190);ctx.fillStyle="#ffffff";ctx.font="700 34px sans-serif";ctx.fillText("PROJECT ATLAS TRACKER · SEASON REPORT",100,100);ctx.font="900 76px sans-serif";ctx.fillText(String(d.selectedSeasonLabel),100,190);ctx.font="600 32px sans-serif";ctx.fillStyle="#b9cad8";ctx.fillText(`${league.league_name||"League"} · ${league.position_display||"Position unknown"}`,100,240);
    const boxes=[["WINS",m.wins],["DRAWS",m.draws],["LOSSES",m.losses],["GOALS",`${m.goals_for}:${m.goals_against}`]];boxes.forEach((b:any,i:number)=>{const x=70+i*250;ctx.fillStyle="#0d2032";ctx.fillRect(x,310,220,150);ctx.fillStyle="#8ea5b9";ctx.font="700 22px sans-serif";ctx.fillText(String(b[0]),x+20,350);ctx.fillStyle="#fff";ctx.font="900 58px sans-serif";ctx.fillText(String(b[1]??"–"),x+20,425);});
    ctx.fillStyle="#fff";ctx.font="800 36px sans-serif";ctx.fillText(awards===d.seasonReport?.manual?.awards?"Manager awards":"Tracker awards",70,550);
    const maxAwards=format==="square"?3:5;(awards.slice(0,maxAwards)).forEach((a:any,i:number)=>{const y=600+i*118;ctx.fillStyle=i%2?"#0a1a2a":"#0d2235";ctx.fillRect(70,y,940,92);ctx.fillStyle="#20df83";ctx.font="700 20px sans-serif";ctx.fillText(String(a.award_label||a.label||"Award").toUpperCase(),95,y+31);ctx.fillStyle="#fff";ctx.font="800 30px sans-serif";ctx.fillText(String(a.display_name||"–"),95,y+70);});
    ctx.fillStyle="#8ea5b9";ctx.font="500 20px sans-serif";ctx.fillText("Created locally with Project Atlas Tracker · data as recorded in the season report",70,H-48);
    const link=document.createElement("a");link.download=`Atlas_Season_Card_${format}_${String(d.selectedSeasonLabel).replace('/','-')}.png`;link.href=canvas.toDataURL("image/png");link.click();
}

async function renderSeasonReport(): Promise<void> {
    const fallback = Number(currentSnapshot()?.season_index ?? 0);
    const selected = state.seasonReportSeasonIndex ?? fallback;
    const d = await api(`/api/careers/${state.careerId}/analysis?snapshot_id=${state.snapshotId}&season_index=${selected}`);
    currentSeasonReportData=d;
    state.seasonReportSeasonIndex = Number(d.selectedSeasonIndex);
    const report=d.seasonReport||{}, reportStatus=report.season_complete?statusBadge("Complete","good"):statusBadge("In progress","blue");
    const active=state.seasonReportTab||"overview";
    const body=active==="competitions"?seasonReportCompetitions(d):active==="squad"?seasonReportSquad(d):active==="transfers"?seasonReportTransfers(d):active==="awards"?seasonReportAwards(d):active==="quality"?seasonReportQuality(d):seasonReportOverview(d);
    content.innerHTML = `<div class="content-inner wide season-report-page">${pageHead("Season report", `${esc(d.selectedSeasonLabel)} · structured career report`, `<button class="button" data-season-report-print>Print / PDF</button><button class="button" data-season-report-csv>CSV</button><button class="button" data-season-report-image="square">Square PNG</button><button class="button primary" data-season-report-image="portrait">Portrait PNG</button>`)}<div class="page-filter-bar">${seasonReportPicker(d.seasonOptions||[],Number(d.selectedSeasonIndex))}<span class="filter-hint">${reportStatus} Automatic and custom awards remain separate.</span></div>${seasonReportTabs(active)}${body}</div>`;
}

async function renderAnalysis(): Promise<void> {
    const fallback = Number(currentSnapshot()?.season_index ?? 0);
    const selected = state.analysisSeasonIndex ?? fallback;
    const active = state.route === "commission" ? "commission" : state.analysisTab || "overview";
    if (active === "commission") {
      const commission = await api(`/api/careers/${state.careerId}/commission?season_index=${selected}`);
      state.analysisSeasonIndex = Number(commission.selectedSeasonIndex);
      const reportCache = await api(`/api/careers/${state.careerId}/commission/report-cache?snapshot_id=${Number(commission.snapshot_id)}&mode=team_identity`).catch(()=>({state:"missing"}));
      const body = technicalCommission(commission, reportCache);
      const filter = `<div class="page-filter-bar">${periodPicker(commission.seasonOptions || [], Number(commission.selectedSeasonIndex), "analysis")}<span class="filter-hint">${esc(commission.detailed_metric_scope || "Position and MatchStats coverage are shown for this season.")}</span></div>`;
      content.innerHTML = `<div class="content-inner wide">${pageHead(state.route==="commission"?"Technical commission":"Analysis", `${esc(commission.managed_team_name||"Active career")} · ${esc(commission.selectedSeasonLabel)}`, `<button class="button" data-route="results">Results</button><button class="button" data-route="squad">Squad</button>`)}${state.route==="commission"?"":analysisTabs(active)}${filter}${body}</div>`;
      return;
    }
    const d = await api(`/api/careers/${state.careerId}/analysis?snapshot_id=${state.snapshotId}&season_index=${selected}`);
    state.analysisSeasonIndex = Number(d.selectedSeasonIndex);
    const leagueContext = d.metrics?.league_context || {};
    const placementMetric = leagueContext.mode === "current"
      ? {title: "League position", value: leagueContext.position ? `#${num(leagueContext.position)}` : "–", sub: leagueContext.league_name || "current league"}
      : {title: "Highest league", value: leagueContext.league_name || "–", sub: leagueContext.position ? `Best position there: #${num(leagueContext.position)} · ${esc(leagueContext.season_label || "")}` : "no reliable position"};
    const body = active === "performance" ? analysisMatchIntelligence(d) : active === "squad" ? analysisSquad(d) : active === "seasons" ? analysisSeasons(d) : analysisOverview(d, placementMetric);
    const filter = active === "seasons" ? '<div class="page-filter-bar"><span class="filter-hint">The season comparison shows all available seasons side by side.</span></div>' : `<div class="page-filter-bar">${periodPicker(d.seasonOptions || [], Number(d.selectedSeasonIndex), "analysis")}<span class="filter-hint">${active==="performance"?"Only clearly linked detailed FC26 matches are included in this analysis.":"Tables and charts use the same selection."}</span></div>`;
    content.innerHTML = `<div class="content-inner wide">${pageHead("Analysis", `career metrics · ${esc(d.selectedSeasonLabel)}`, `<button class="button" data-route="records">Records</button><button class="button" data-route="chronology">Career timeline</button>`)}${analysisTabs(active)}${filter}${body}</div>`;
}

async function renderRecords(): Promise<void> {
    const selected = state.recordsSeasonIndex ?? -1;
    const d = await api(`/api/careers/${state.careerId}/analysis?snapshot_id=${state.snapshotId}&season_index=${selected}`);
    state.recordsSeasonIndex = Number(d.selectedSeasonIndex);
    content.innerHTML = `<div class="content-inner wide">${pageHead("Records", `Player, match, streak and transfer records · ${esc(d.selectedSeasonLabel)}`, `<button class="button" data-route="analysis">Back to analysis</button>`)}
      <div class="page-filter-bar">${periodPicker(d.seasonOptions || [], Number(d.selectedSeasonIndex), "records")}<span class="filter-hint">The entire career is analysed by default.</span></div>
      ${recordCatalog(d.records || {})}
      <div class="grid two-col analysis-grid"><section class="card pad"><h3 class="card-title">Calculation rule</h3><p class="chart-note">All of a player’s competitions are summed within the selected period. Manual legacy seasons and snapshot seasons are joined by calendar year.</p></section>${qualityPanel(d.quality)}</div>
    </div>`;
}
